import h5py, numpy as np

def decode_char(ds):
    return ''.join(chr(int(x)) for x in np.array(ds).squeeze())

def matlab_class(obj):
    cls=obj.attrs.get('MATLAB_class',b'')
    if isinstance(cls,(bytes,np.bytes_)):
        return bytes(cls).decode()
    return cls

def make_obj_array(shape, items):
    arr=np.empty(shape,dtype=object)
    for idx,val in zip(np.ndindex(shape),items):
        arr[idx]=val
    return arr

def read_any(f,obj):
    if isinstance(obj,h5py.Reference):
        if not obj:
            return None
        obj=f[obj]
    cls=matlab_class(obj)
    if isinstance(obj,h5py.Group):
        return {k: read_any(f,obj[k]) for k in obj.keys()}
